test('retryN retries on rejection up to n additional times', async () => {
  let attempts = 0;
  const fn = () => { attempts++; return attempts >= 3 ? Task.resolve('ok') : Task.reject('not yet'); };
  const r = await Task.retryN(2, fn).promise;
  expect(attempts).toBe(3);
  expect(r.isOk).toBe(true);
expect(r.value).toBe('ok');
});
